-- Generated by Loom
-- Generator: hub
-- Hash function: SHA256
{{ config(materialized='incremental', incremental_strategy='append') }}
SELECT DISTINCT
    LOWER(TO_HEX(SHA256(CAST(UPPER(TRIM(CAST(customer_id AS STRING))) AS BYTES)))) AS customer_hk,
    UPPER(TRIM(CAST(customer_id AS STRING))) AS customer_id
FROM {{ ref('stg_customers') }}
WHERE customer_id IS NOT NULL
{% if is_incremental() %}
  AND LOWER(TO_HEX(SHA256(CAST(UPPER(TRIM(CAST(customer_id AS STRING))) AS BYTES)))) NOT IN (
    SELECT target.customer_hk FROM {{ this }} AS target
  )
{% endif %}
